//Import Action to copy breadcrumb items from local state to redux state
import { setBreadcrumbItems } from "../../../store/actions"
import ReportTable from "./ReportTable"

const UserReport = props => {
  const breadcrumbItems = [
    { title: "Incase360", link: "#" },
    { title: "CSV Report", link: "#" },
  ]

  useEffect(() => {
    props.setBreadcrumbItems("CSV Report", breadcrumbItems)
  })

  return (
    <React.Fragment>
      <MetaTags>
        <title>CSV Report - User | Incase360</title>
      </MetaTags>
      <CustomProvider theme="dark">
        <ReportTable />
      </CustomProvider>
    </React.Fragment>
  )
}

export default connect(null, { setBreadcrumbItems })(UserReport)
