const initialState = {
    items: [],
    loading: false,
    count: 0,
    error: null,
};

export const FileSharing = (state = initialState, action) => {
    switch (action.type) {
        case "FileSharingBegin":
            return {
                ...state,
                loading: true,
                error: null,
            };
        case "FileSharingSuccess":
            return {
                ...state,
                items: action.data,
                count: action.count,
                loading: false,
            };
        case "FileSharingFailure":
            return {
                ...state,
                items: [],
                loading: false,
                error: action.data,
            };
        default:
            return state;
    }
};

