import React, { useEffect, useState } from "react"
import { Button, Col, Grid, Input, Row, SelectPicker } from "rsuite"
import { connect } from "react-redux"
import { ApiCall } from "common/ActionApiCall/ApiCall"
import { FileUploader } from "react-drag-drop-files"
import { ShowNotification } from "common/ShowNotification"

function UploadCSV(props) {
  const [loading, setLoading] = useState(false)
  const [action, setAction] = useState(false)
  const [request, setRequest] = useState({
    token: props?.token,
    file_csv: null,
    reportType: null,
  })

  const handleSubmit = () => {
    request?.file_csv &&
      request?.reportType && [
        setLoading(true),
        ApiCall(request, "convertToPremilinaryReport", false, result => {
          if (result?.data?.response === "success") {
            //   setActiveCountData(result?.data?.responseData)
            // ShowNotification(result?.data?.message, "success")
            const link = document.createElement("a")
            link.target = "_blank"
            link.href = result?.data?.message
            document.body.appendChild(link)
            link.click()
            link.parentNode.removeChild(link)
            ShowSwal("", "Successfully Download!", "success", "Ok")
          } else {
            //   setRequest({ ...request, file_csv: null })
            ShowNotification(
              result?.data?.message ? result?.data?.message : "Somthing Wrong",
              "danger"
            )
          }
          setAction(!action)
          setLoading(false)
        }),
      ]
  }

  const selectData = [
    {
      label: "Upload Bar Code",
      value: "Upload Bar Code",
    },
    {
      label: "Preliminary Report",
      value: "Preliminary Report",
    },
    {
      label: "Interim Report",
      value: "Interim Report",
    },
    {
      label: "Final Report",
      value: "Final Report",
    },
  ]

  useEffect(() => {
    setRequest({ ...request, file_csv: null })
  }, [action])

  return (
    <div className="card">
      <div className="card-header">
        <h5>Generate Preliminary Report</h5>
      </div>
      <div className="card-Body m-2">
        <Grid fluid>
          <Row className="show-grid">
            <Col lg={24} md={24} sm={24} xs={24} className="mt-1">
              <SelectPicker
                label={"Select Report Type"}
                block
                data={selectData}
                onChange={e => setRequest({ ...request, reportType: e })}
              />
            </Col>
            <Col lg={18} md={18} sm={24} xs={24} className="mt-2">
              <FileUploader
                name="file_csv"
                types={["csv", "xls", "xlsx"]}
                handleChange={e => setRequest({ ...request, file_csv: e })}
                onTypeError={e =>
                  e &&
                  setRequest({
                    ...request,
                    file_csv: null,
                  })
                }
              />
            </Col>
            <Col lg={6} md={6} sm={24} xs={24} className="mt-0">
              <Button
                appearance="primary"
                color="blue"
                disabled={loading}
                style={{ marginTop: "1.2em" }}
                onClick={() => handleSubmit()}
                block
              >
                {loading ? "Loading..." : "Submit"}
              </Button>
            </Col>
          </Row>
        </Grid>
      </div>
    </div>
  )
}

const mapStateToProps = state => ({
  token: state.Login.token,
})

export default connect(mapStateToProps)(UploadCSV)
