const initialState = {
    items: [],
    loading: false,
    count: 0,
    error: null,
};

const deatilsState = {
    items: [],
    loading: false,
    error: null
}

const letterheadState = {
    items: [],
    loading: false,
    count: 0,
    error: null
}

const approverUserState = {
    items: [],
    loading: false,
    error: null
}

export const UserDetails = (state = deatilsState, action) => {
    switch (action.type) {
        case "UserDetailsBegin":
            return {
                ...state,
                loading: true,
                error: null,
            };
        case "UserDetailsSuccess":
            return {
                ...state,
                items: action.data,
                loading: false,
            };
        case "UserDetailsFailure":
            return {
                ...state,
                items: [],
                loading: false,
                error: action.data,
            };
        default:
            return state;
    }
};

