import React from "react"
import HomeIcon from "@rsuite/icons/legacy/Home"
import { Header, Navbar, Nav } from "rsuite"
import { Link } from "react-router-dom"
// import {width, he}
import logo from "../../assets/images/logo.png";

function HomeHeader() {
  return (
    <div className="main-header">
      <div className="container">
        <Header>
          <Navbar appearance="subtle">
            <Navbar.Brand>
              <Link to="/">
                <img
                  alt=""
                  style={{ width: "12em" }}
                  className="logo"
                  src={logo}
                />
              </Link>
            </Navbar.Brand>

            <Nav pullRight>
              {/* <Nav.Item icon={<HomeIcon />}>
                <Link to="/">Home</Link>
              </Nav.Item> */}
             {/*  <Nav.Item>
                <Link to="/register">Create Account</Link>
              </Nav.Item> */}
               <Nav.Item>
                <Link to="https://presolv360.com/about_us" style={{"font-weight": "600",  "color": "#0e5688", "font-size": "16px" }}><b>About</b></Link>
              </Nav.Item>
              <Nav.Item>
                <Link to="/https://mediation.presolv360.com/login">
                  <button className="custom-btn" >Login</button>
                </Link>
              </Nav.Item>
            </Nav>
          </Navbar>
        </Header>
      </div>
    </div>
  )
}

export default HomeHeader
