const initialState = {
  items: [],
  loading: false,
  error: null,
}

const OfferList = (state = initialState, action) => {
  switch (action.type) {
    case "OffersListBegin":
      return {
        ...state,
        loading: true,
        error: null,
      }
    case "OffersListSuccess":
      return {
        ...state,
        items: action.data,
        loading: false,
      }
    case "OffersListFailure":
      return {
        ...state,
        items: [],
        loading: false,
        error: action.data,
      }
    default:
      return state
  }
}

export default OfferList
