import axios from "axios"
import { ApiRoute } from "common/ApiRoute"

const api_url = ApiRoute

export const getDataNotice = requestPayload => {
  //   const role_name = role === 2 ? "admin" : role === 1 ? "mediator" : "user"

  return dispatch => {
    dispatch({ type: "DraftNoticeBegin" })
    axios
      .post(api_url + "noticeData", requestPayload)
      .then(result => {
        dispatch({
          type: "DraftNoticeSuccess",
          data: result.data?.responseData,
        })
      })
      .catch(error => {
        dispatch({
          type: "DraftNoticeFailure",
          data: error,
        })
      })
  }
}
