import axios from "axios"
import { ApiRoute } from "common/ApiRoute"

const api_url = ApiRoute

export const getPartyReply = requestPayload => {
  let formData = new FormData()
  Object.entries(requestPayload).map(([key, value]) => {
    formData.append(key, value)
  })
  //   const role_name = role === 2 ? "admin" : role === 1 ? "mediator" : "user"

  return dispatch => {
    dispatch({ type: "PartyReplyBegin" })
    axios
      .post(api_url + "user/party-replyview", formData)
      .then(result => {
        dispatch({
          type: "PartyReplySuccess",
          data: result.data.responseData,
          count: result.data.count,
        })
      })
      .catch(error => {
        dispatch({
          type: "PartyReplyFailure",
          data: error,
        })
      })
  }
}
