import axios from "axios"
import { ApiRoute } from "common/ApiRoute"

const api_url = ApiRoute

export const getCsvReport = requestPayload => {
  //   const role_name = role === 2 ? "admin" : role === 1 ? "mediator" : "user"

  return dispatch => {
    dispatch({ type: "CsvReportBegin" })
    axios
      .post(api_url + "csvReport", requestPayload)
      .then(result => {
        dispatch({
          type: "CsvReportSuccess",
          data: result.data.responseData,
          count: result.data.count,
        })
      })
      .catch(error => {
        dispatch({
          type: "CsvReportFailure",
          data: error,
        })
      })
  }
}
